import { json, Router, type ErrorRequestHandler } from 'express';
import { z } from 'zod';
import { pluginMetricProperties } from '../config/pluginMetrics';
import type { TelemetryService } from '../services/TelemetryService';
import { isLocalBrowserRequest } from './library/middleware';
import { getTelemetryMode } from '../config/telemetryPolicy';
import { getConfigManager } from '../services/ConfigManager';

const metricBody = z.object({
  event: z.string(),
  properties: z.record(z.string(), z.unknown()),
});

export const createTelemetryRouter = (
  telemetry?: Pick<TelemetryService, 'track'>,
): Router => {
  const router = Router();
  router.get('/', (_req, res) => {
    const mode = getTelemetryMode();
    res.setHeader('Cache-Control', 'no-store');
    res.json({
      mode,
      ...(mode === 'metrics'
        ? { distinctId: getConfigManager().getPluginTelemetryId() }
        : {}),
    });
  });
  router.post('/events', json({ limit: '8kb' }), (req, res) => {
    if (!isLocalBrowserRequest(req)) return res.sendStatus(403);
    if (getTelemetryMode() !== 'metrics') return res.sendStatus(204);
    const body = metricBody.safeParse(req.body);
    if (!body.success) return res.sendStatus(400);
    const properties = pluginMetricProperties(
      body.data.event,
      body.data.properties,
    );
    if (!properties) return res.sendStatus(400);
    telemetry?.track(body.data.event, {
      ...properties,
      source: 'visual_editor',
    });
    return res.sendStatus(204);
  });
  const rejectInvalidBody: ErrorRequestHandler = (
    error: unknown,
    _req,
    res,
    next,
  ) => {
    if (typeof error === 'object' && error !== null && 'type' in error) {
      if (error.type === 'entity.too.large') {
        res.sendStatus(413);
        return;
      }
      if (error.type === 'entity.parse.failed') {
        res.sendStatus(400);
        return;
      }
    }
    next(error);
  };
  router.use(rejectInvalidBody);
  return router;
};
